scenarios.example_code:
import { createCampaign, computeSegment } from '@projexlight/sdk-campaign';
const { campaign_id } = await createCampaign({
  tenant_id, name: 'EU Q3 Nurture', owner_persona_id, channels: ['email','linkedin'],
});
const { segment_id, member_count } = await computeSegment({
  campaign_id, name: 'eu-pro-tier',
  definition: { kind: 'sql', query: "SELECT id FROM crm.contact WHERE region='EU' AND plan='pro'" },
});

import { publishJourney } from '@projexlight/sdk-campaign';
await publishJourney({
  campaign_id, name: 'eu-pro-nurture-v1',
  steps: [
    { id: 's1', kind: 'send-email', template: 'eu-pro-nurture-1' },
    { id: 's2', kind: 'wait', duration: 'P3D' },
    { id: 's3', kind: 'branch', condition: 'email.opened', true: 's4', false: 's5' },
    { id: 's4', kind: 'send-email', template: 'eu-pro-demo-invite' },
    { id: 's5', kind: 'send-email', template: 'eu-pro-nurture-1-retry' },
  ],
});

subscribeEvents('lead_scoring.score.changed.v1', async (e) => {
  if (e.payload.new_score < 70) return;
  await enrollInJourney({ journey_id: 'eu-pro-nurture-v1', contact_id: e.payload.lead_id });
});

subscribeEvents('consent.receipt.revoked.v1', async (e) => {
  if (e.payload.kind === 'marketing' && e.payload.allowed === false) {
    await haltRunsForContact({ contact_id: e.payload.contact_id });
  }
});

import { haltJourney } from '@projexlight/sdk-campaign';
await haltJourney({
  journey_id, reason: 'wrong-template-in-step-3',
  halted_by_persona_id,
});
